import{_ as t,c as o,o as a,ae as d}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Products","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/products/index.md","filePath":"api/rest-api/shop/products/index.md"}'),r={name:"api/rest-api/shop/products/index.md"};function s(i,e,c,n,l,p){return a(),o("div",null,e[0]||(e[0]=[d('<h1 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h1><p>The Products menu is the catalog surface a shopper browses and searches. It returns product listings, full single-product detail, search results, booking slots for bookable products, and a set of sub-resources for the heavier data attached to a product (images, prices, attribute values, and type-specific structure).</p><h2 id="listing-search-and-detail" tabindex="-1">Listing, search and detail <a class="header-anchor" href="#listing-search-and-detail" aria-label="Permalink to &quot;Listing, search and detail&quot;">​</a></h2><ul><li>The <strong>list</strong> endpoint returns a paginated catalog with filtering, sorting and faceted attribute filters. <strong>Search</strong> is the same listing surface with a search term applied.</li><li>The <strong>single product</strong> endpoint returns one product&#39;s full detail, with its categories, images, variants and type-specific blocks embedded — no follow-up calls needed for the common fields.</li><li><strong>Booking slots</strong> return the available time slots for a bookable product.</li></ul><p>Pass <code>locale</code> and <code>channel</code> to receive catalog data for a specific language and store. Filters beyond the basics (price, category, type, new/featured) cover any filterable attribute the catalog exposes.</p><h2 id="sub-resources" tabindex="-1">Sub-resources <a class="header-anchor" href="#sub-resources" aria-label="Permalink to &quot;Sub-resources&quot;">​</a></h2><p>For data that is heavy or addressed on its own, products expose dedicated sub-resource endpoints (e.g. a variant&#39;s images, customer-group prices, attribute values, and the structure that varies by product type). The two sub-resource pages below describe what each one returns and when to call it instead of relying on the inlined detail.</p><h2 id="filtering-sorting-and-paging" tabindex="-1">Filtering, Sorting and Paging <a class="header-anchor" href="#filtering-sorting-and-paging" aria-label="Permalink to &quot;Filtering, Sorting and Paging&quot;">​</a></h2><p>Every filter is a query parameter on the listing, and they are <strong>AND-combined</strong> — more filters narrow the result, never widen it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Notes</th></tr></thead><tbody><tr><td><code>query</code></td><td>Search term, matched against SKU and name.</td></tr><tr><td><code>type</code></td><td>One of <code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, <code>virtual</code>, <code>downloadable</code>, <code>booking</code>.</td></tr><tr><td><code>category_id</code></td><td>Products in that category. <code>categoryId</code> also accepted.</td></tr><tr><td><code>price</code></td><td>Compound range <code>min,max</code> — the comma is a separator, never a thousands mark. <code>price_from</code> / <code>price_to</code> do the same job.</td></tr><tr><td><code>new</code>, <code>featured</code></td><td>The merchandising flags.</td></tr><tr><td><code>&lt;attribute_code&gt;</code></td><td>Any filterable attribute, e.g. <code>?color=3&amp;size=4,5</code>. Values are option <strong>ids</strong>, not labels.</td></tr><tr><td><code>sort</code>, <code>order</code></td><td><code>name-asc</code>, <code>price-desc</code>, <code>created_at-desc</code>, and the rest; or a bare key plus <code>order</code>.</td></tr><tr><td><code>page</code>, <code>per_page</code></td><td>Default 30, capped at 50.</td></tr></tbody></table><p>An unrecognised <code>sort</code> token does not error — it silently falls back to the default catalog order, so a typo looks like broken sorting. A filter on an attribute that is not flagged filterable is likewise ignored.</p><h2 id="card-fields-versus-full-detail" tabindex="-1">Card Fields Versus Full Detail <a class="header-anchor" href="#card-fields-versus-full-detail" aria-label="Permalink to &quot;Card Fields Versus Full Detail&quot;">​</a></h2><p>The listing returns a ~21-field card: identity, prices with their <code>formatted*</code> twins, the merchandising flags, one <code>baseImageUrl</code>, and the per-customer wishlist and compare flags. Everything heavy — the image gallery, categories, variants, bundle options, downloadable links, customizable options, related products — is detail-only.</p><p>Single-product detail inlines all of it, so a product page needs one call. Every relation key is present on every product regardless of type, as an empty array when it does not apply, so render on array length rather than on <code>type</code>.</p><p>Detail is addressed by <strong>numeric id</strong>; a slug answers <code>404</code>. A storefront routed on slugs resolves them through the GraphQL <code>product(urlKey:)</code> lookup, or by matching <code>urlKey</code> from the listing.</p><h2 id="per-customer-flags" tabindex="-1">Per-Customer Flags <a class="header-anchor" href="#per-customer-flags" aria-label="Permalink to &quot;Per-Customer Flags&quot;">​</a></h2><p><code>isInWishlist</code> and <code>isInCompare</code> come back on every card and on detail, so a grid can highlight both icons without touching those menus. Send the customer token — both are <code>0</code> for guests — and note REST returns them as the integers <code>1</code> / <code>0</code> where GraphQL returns the strings.</p><h2 id="product-types" tabindex="-1">Product Types <a class="header-anchor" href="#product-types" aria-label="Permalink to &quot;Product Types&quot;">​</a></h2><p>Seven types share one payload shape, each populating its own block: <code>variants</code> and <code>superAttributes</code> for configurable, <code>bundleOptions</code> for bundle, <code>groupedProducts</code> for grouped, <code>downloadableLinks</code> and <code>downloadableSamples</code> for downloadable, <code>bookingProducts</code> for booking. Booking products need a second call for their bookable times — see Booking Slots below.</p><p>Check <code>isSaleable</code> before enabling add-to-cart: a product can be published and still out of stock, and only that flag combines the checks.</p><h2 id="currency-and-locale" tabindex="-1">Currency and Locale <a class="header-anchor" href="#currency-and-locale" aria-label="Permalink to &quot;Currency and Locale&quot;">​</a></h2><p><code>X-Currency</code> converts prices and changes the symbol in the <code>formatted*</code> fields; <code>X-Locale</code> changes names, descriptions, and attribute values. Both fall back to the channel default when omitted or when the value is not enabled on the channel.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/products/get-products.html">Products</a></td><td><code>GET /api/shop/products</code></td><td>Paginated, filterable, sortable product listing.</td></tr><tr><td><a href="/api/rest-api/shop/products/search-product.html">Search Products</a></td><td><code>GET /api/shop/products?query=</code></td><td>The same listing endpoint with a search term and filters applied.</td></tr><tr><td><a href="/api/rest-api/shop/products/get-product.html">Single Product</a></td><td><code>GET /api/shop/products/{id}</code></td><td>Full detail for one product.</td></tr><tr><td><a href="/api/rest-api/shop/products/get-booking-slots.html">Booking Slots</a></td><td><code>GET /api/shop/booking-slots?id=&amp;date=</code></td><td>Bookable slots for one booking product on a given date.</td></tr><tr><td><a href="/api/rest-api/shop/products/product-subresources.html">Product Sub-Resources</a></td><td><code>GET /api/shop/products/{id}/…</code></td><td>Images, prices and attribute values per product.</td></tr><tr><td><a href="/api/rest-api/shop/products/product-type-subresources.html">Product Type Sub-Resources</a></td><td><code>GET /api/shop/products/{id}/variants</code>, <code>…/bundle-options</code>, <code>…/downloadable-links</code>, <code>…/booking-products</code></td><td>Type-specific structure for configurable, bundle, grouped, downloadable and booking products.</td></tr></tbody></table><p>All Product endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',25)]))}const g=t(r,[["render",s]]);export{h as __pageData,g as default};
